/**
 * Merge command handler
 */
import { mergeCommand, parseMergeArgs } from "./command.js";
import { showHeader } from "../../utils/index.js";
import { parseArgsOrThrow } from "../../shared/args.js";
export async function handleMergeCommand(args) {
    showHeader();
    await mergeCommand(parseArgsOrThrow(parseMergeArgs, "merge", args));
}
